{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be a dict")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"core_distance missing for node {node}")

    n = len(nodes)

    # Compute mutual reachability for each edge, canonicalize endpoints
    edges = []
    for entry in distances:
        u, v, d = entry[0], entry[1], entry[2]
        if u not in core_distance:
            raise ValueError(f"core_distance missing for node {u}")
        if v not in core_distance:
            raise ValueError(f"core_distance missing for node {v}")
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize: smaller string first
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))

    # Sort by mutual reachability, then by canonicalized endpoint IDs for determinism
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find for Kruskal
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
